export type DueBefore = IsoTimestamp | CalendarDate;

/** Expands `open` / `closed` in place and drops duplicate members. */
export function expandIssueStatuses(
  values: readonly IssueStatusFilter[],
): IssueStatus[] {
  const expanded: IssueStatus[] = [];
  const seen = new Set<string>();
  for (const value of values) {
    const members: readonly IssueStatus[] =
      value === "open"
        ? OPEN_ISSUE_STATUSES
        : value === "closed"
          ? CLOSED_ISSUE_STATUSES
          : [value];
    for (const status of members) {
      if (seen.has(status)) continue;
