const CALENDAR_DATE = /^\d{4}-\d{2}-\d{2}$/;
const ISO_TIMESTAMP =
  /^(\d{4}-\d{2}-\d{2})T(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d(?:\.\d+)?Z$/;

/** True for a real UTC calendar date `YYYY-MM-DD`. */
export function isCalendarDate(value: string): boolean {
  if (!CALENDAR_DATE.test(value)) return false;
  const [year, month, day] = value.split("-").map(Number) as [
    number,
    number,
    number,
  ];
  const date = new Date(Date.UTC(year, month - 1, day));
  return (
    date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 &&
    date.getUTCDate() === day
  );
}

/** True for a full UTC ISO-8601 timestamp with a `Z` suffix. */
export function isIsoTimestamp(value: string): boolean {
  const match = ISO_TIMESTAMP.exec(value);
  const date = match?.[1];
  if (date === undefined) return false;
  return isCalendarDate(date);
}

/** A due-before value the list filter accepts. */
export function isDueBefore(value: string): boolean {
  return isCalendarDate(value) || isIsoTimestamp(value);
}

/**
 * Exclusive upper bound for `due_before`.
 * A calendar date includes the whole UTC day; a timestamp is itself.
 */
export function dueBeforeExclusiveBound(value: string): IsoTimestamp {
  if (isCalendarDate(value)) {
    const [year, month, day] = value.split("-").map(Number) as [
      number,
      number,
      number,
    ];
    return toIsoTimestamp(new Date(Date.UTC(year, month - 1, day + 1)));
  }
  return toIsoTimestamp(value);
}

