/**
 * The URL is the single source of truth for the issue list filter: a filtered
 * view has to be shareable and survive a reload, and the server component that
 * renders the page parses the very same query string. These two functions are
 * that codec, kept pure so both sides can use them.
 *
 * `assignee=none` is unassigned. `assignee=me` and `author=me` travel
 * unchanged; the service resolves them against the signed-in user. Omitting
 * either parameter means "do not filter on it".
 *
 * `status` is a comma list. `open` and `closed` expand to their members here.
 * Unknown status tokens are dropped. `archived=1` mixes archived issues in;
 * `archived=only` lists archived issues alone.
 */
import { isCalendarDate, isDueBefore, isIsoTimestamp } from "@/lib/date";
import type { CalendarDate, LabelId, ProjectId, IsoTimestamp, UserId } from "@/types/common";
import {
  expandIssueStatuses,
  ISSUE_PRIORITIES,
  ISSUE_STATUSES,
  ISSUE_STATUS_GROUPS,
  ME_TOKEN,
  type IssueFilter,
  type IssuePriority,
  type IssueStatus,
  type IssueStatusFilter,
  type MeToken,
} from "@/types/issue";

export const UNASSIGNED_TOKEN = "none";
export { ME_TOKEN };

