  );
}

function parseActor(raw: string): UserId | MeToken {
  return raw === ME_TOKEN ? ME_TOKEN : (raw as UserId);
}

function parseDueBefore(
  raw: string,
): IsoTimestamp | CalendarDate | undefined {
  if (isCalendarDate(raw)) return raw as CalendarDate;
  if (isIsoTimestamp(raw)) return raw as IsoTimestamp;
  return undefined;
}

export function parseIssueFilterParams(params: ReadableParams): IssueFilter {
  const statuses = expandIssueStatuses(
    splitList(params.get("status")).filter(isStatusFilter),
  );
  const priorities = splitList(params.get("priority")).filter(
    (value): value is IssuePriority =>
      ISSUE_PRIORITIES.includes(value as IssuePriority),
  );
  const labelIds = splitList(params.get("label")) as readonly LabelId[];
  const project = params.get("project");
  const assignee = params.get("assignee");
  const author = params.get("author");
  const query = params.get("q");
  const dueRaw = params.get("due_before");
  const dueBefore =
    dueRaw !== null && isDueBefore(dueRaw) ? parseDueBefore(dueRaw) : undefined;
  const archived = params.get("archived");

  const filter: IssueFilter = {
    ...(project !== null ? { projectId: project as ProjectId } : {}),
    ...(statuses.length > 0 ? { status: statuses } : {}),
    ...(priorities.length > 0 ? { priority: priorities } : {}),
    ...(assignee !== null
      ? {
          assigneeId:
            assignee === UNASSIGNED_TOKEN ? null : parseActor(assignee),
        }
      : {}),
    ...(author !== null ? { authorId: parseActor(author) } : {}),
    ...(labelIds.length > 0 ? { labelIds } : {}),
    ...(query !== null && query.length > 0 ? { query } : {}),
    ...(dueBefore !== undefined ? { dueBefore } : {}),
    ...(archived === "1" ? { includeArchived: true } : {}),
    ...(archived === "only" ? { archivedOnly: true } : {}),
  };

  return filter;
}

/** Adapts a Next.js `searchParams` record to the URL codec. */
export function parseIssueFilterSearchParams(
  search:
    | ReadableParams
    | Readonly<Record<string, string | readonly string[] | undefined>>,
): IssueFilter {
  if ("get" in search && typeof search.get === "function") {
    return parseIssueFilterParams(search);
  }
  const record = search as Readonly<
    Record<string, string | readonly string[] | undefined>
  >;
  return parseIssueFilterParams({
    get(name: string): string | null {
      const value = record[name];
      if (value === undefined) return null;
      return Array.isArray(value) ? value.join(",") : value;
    },
  });
}

