import { z } from "zod";
import type { CalendarDate } from "@/types/common";
import type { IssuePriority, IssueStatus } from "@/types/issue";
import { ME_TOKEN } from "@/types/issue";
import {
  archiveScopeSchema,
  isoTimestampSchema,
  issueIdSchema,
  labelIdSchema,
  orgIdSchema,
  pageRequestSchema,
  projectIdSchema,
  userIdSchema,
} from "./common";

export const issuePrioritySchema = z.enum([
  "none",
  "low",
  "medium",
  "high",
  "urgent",
]);

/** A concrete status or one of the `open` / `closed` groups. */
export const issueStatusFilterSchema = z.union([
  issueStatusSchema,
  z.enum(["open", "closed"]),
]);

const issueStatusListSchema = z.array(issueStatusFilterSchema);

/**
 * A status selection: an array, or the comma list the URL and the export
 * script send. Unknown tokens fail the parse — the URL codec drops them
 * before they get here.
 */
export const issueStatusSelectionSchema = z.union([
  issueStatusListSchema,
  z.string().transform((value, ctx) => {
    const parts = value
      .split(",")
      .map((part) => part.trim())
      .filter((part) => part.length > 0);
    const parsed = issueStatusListSchema.safeParse(parts);
    if (!parsed.success) {
      for (const issue of parsed.error.issues) ctx.addIssue(issue);
      return z.NEVER;
    }
    return parsed.data;
  }),
]);

const issuePriorityListSchema = z.array(issuePrioritySchema);

export const issuePrioritySelectionSchema = z.union([
  issuePriorityListSchema,
  z.string().transform((value, ctx) => {
    const parts = value
      .split(",")
      .map((part) => part.trim())
      .filter((part) => part.length > 0);
    const parsed = issuePriorityListSchema.safeParse(parts);
    if (!parsed.success) {
      for (const issue of parsed.error.issues) ctx.addIssue(issue);
      return z.NEVER;
    }
    return parsed.data;
  }),
]);

/** `me` stays `me`. `none` is unassigned. A user id passes through. */
export const assigneeFilterSchema = z
  .union([
    z.literal(ME_TOKEN),
    z.literal("none").transform(() => null),
    z.null(),
    userIdSchema,
  ])
  .optional();

export const authorFilterSchema = z
  .union([z.literal(ME_TOKEN), userIdSchema])
  .optional();

/** A UTC calendar date (the whole day) or a full ISO-8601 timestamp. */
export const dueBeforeSchema = z.union([
  isoTimestampSchema,
  z.iso.date().transform((value) => value as CalendarDate),
]);

