function duePredicate(
  dueBefore: IssueFilterInput["dueBefore"],
): SQL | undefined {
  if (dueBefore === undefined) return undefined;
  return and(
    isNotNull(issues.dueAt),
    lt(issues.dueAt, dueBeforeExclusiveBound(dueBefore)),
  );
}

/** An issue matches only when it carries every listed label. */
function labelPredicate(
  orgId: IssueFilterInput["orgId"],
  labelIds: IssueFilterInput["labelIds"],
): SQL | undefined {
  if (labelIds === undefined || labelIds.length === 0) return undefined;
  const matches = labelIds.map((labelId) =>
    inArray(
      issues.id,
      getDb()
        .select({ id: issueLabels.issueId })
        .from(issueLabels)
        .where(
          and(
            orgPredicate(issueLabels.orgId, orgId),
            eq(issueLabels.labelId, labelId),
          ),
        ),
    ),
  );
  return and(...matches);
}

