 * schema. The listing resolves them against the acting user so a page and
 * an API caller get the same rows.
 */
function resolveActorFilter(
  actor: Actor,
  input: IssueFilterInput,
): IssueFilterInput {
  return {
    ...input,
    ...(input.assigneeId === "me" ? { assigneeId: actor.userId } : {}),
    ...(input.authorId === "me" ? { authorId: actor.userId } : {}),
  };
}

export async function listIssues(
  actor: Actor,
  input: IssueFilterInput,
): Promise<Page<Issue>> {
  assertOrgScope(actor, input.orgId);
  // A cross-project list is an org-wide read; per-project visibility is
  // enforced when the caller opens an individual issue.
  assertCan(actor, "issue:read", orgResource(input.orgId));
  return issueRepo.listIssues(resolveActorFilter(actor, input));
}

