export function toggleStatus(
  filter: IssueFilter,
  status: IssueStatusFilter,
): IssueFilter {
  const current = filter.status ?? [];
  const members = expandIssueStatuses([status]);
  const allSelected = members.every((member) => current.includes(member));
  const next = allSelected
    ? current.filter((value) => !members.includes(value))
    : [...current, ...members.filter((member) => !current.includes(member))];
  const { status: _dropped, ...rest } = filter;
