function withAssignee(filter: IssueFilter, raw: string): IssueFilter {
  if (raw.length === 0) {
    const { assigneeId: _assigneeId, ...rest } = filter;
    return rest;
  }
  if (raw === UNASSIGNED_TOKEN) return { ...filter, assigneeId: null };
  if (raw === ME_TOKEN) return { ...filter, assigneeId: ME_TOKEN };
  return { ...filter, assigneeId: raw as UserId };
}

function duePickerValue(value: string | undefined): string | null {
  if (value === undefined) return null;
  if (isCalendarDate(value)) return value;
  if (isIsoTimestamp(value)) return value.slice(0, 10);
  return null;
}

function withDueBefore(filter: IssueFilter, value: string | null): IssueFilter {
  const { dueBefore: _dueBefore, ...rest } = filter;
  if (value === null || value.length === 0) return rest;
  return { ...rest, dueBefore: value as CalendarDate };
}

function archivedMode(filter: IssueFilter): string {
  if (filter.archivedOnly === true) return "only";
  if (filter.includeArchived === true) return "1";
  return "";
}

function withArchived(filter: IssueFilter, mode: string): IssueFilter {
  const { includeArchived: _include, archivedOnly: _only, ...rest } = filter;
  if (mode === "only") return { ...rest, archivedOnly: true };
  if (mode === "1") return { ...rest, includeArchived: true };
  return rest;
}

