} from "@/types/issue";
import type { SQL } from "drizzle-orm";

/** Statuses whose entry stamps `completed_at`; leaving one clears it again. */
const TERMINAL_STATUSES: readonly IssueStatus[] = ["done", "canceled"];

export async function findIssueById(
60→  orgId: OrgId,
  issueId: IssueId,
): Promise<Issue | null> {
  const row = getDb()
    .select()
    .from(issues)
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .get();
  if (!row) return null;

70→  const labels = await listLabelsForIssues(orgId, [row.id as IssueId]);
  return toIssue(row, (labels[row.id] ?? []).map((label) => label.id));
}

export async function findIssueByNumber(
  orgId: OrgId,
  projectId: ProjectId,
  issueNumber: number,
): Promise<Issue | null> {
  const row = getDb()
80→    .select()
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        eq(issues.projectId, projectId),
        eq(issues.number, issueNumber),
      ),
    )
    .get();
90→  return row ? toIssue(row) : null;
}

/**
 * `null` is unassigned. `undefined` does not filter. The `me` token is
 * resolved by the service before it reaches here; an unresolved token
 * matches nothing rather than every row.
 */
function assigneePredicate(
  assigneeId: IssueFilterInput["assigneeId"],
100→): SQL | undefined {
  if (assigneeId === undefined) return undefined;
  if (assigneeId === null) return isNull(issues.assigneeId);
  if (assigneeId === ME_TOKEN) return sql`1 = 0`;
  return eq(issues.assigneeId, assigneeId);
}

