  authorId: IssueFilterInput["authorId"],
): SQL | undefined {
110→  if (authorId === undefined) return undefined;
  if (authorId === ME_TOKEN) return sql`1 = 0`;
  return eq(issues.authorId, authorId);
}

/** Issues with no due date never match. A calendar date includes that whole UTC day. */
function duePredicate(
  dueBefore: IssueFilterInput["dueBefore"],
): SQL | undefined {
  if (dueBefore === undefined) return undefined;
120→  return and(
    isNotNull(issues.dueAt),
    lt(issues.dueAt, dueBeforeExclusiveBound(dueBefore)),
