}

/** An issue matches only when it carries every listed label. */
function labelPredicate(
  orgId: IssueFilterInput["orgId"],
  labelIds: IssueFilterInput["labelIds"],
130→): SQL | undefined {
  if (labelIds === undefined || labelIds.length === 0) return undefined;
  const matches = labelIds.map((labelId) =>
    inArray(
      issues.id,
      getDb()
        .select({ id: issueLabels.issueId })
        .from(issueLabels)
        .where(
          and(
140→            orgPredicate(issueLabels.orgId, orgId),
            eq(issueLabels.labelId, labelId),
          ),
        ),
    ),
  );
  return and(...matches);
}

/** Builds the shared predicate list behind `listIssues` and its count. */
150→function issueFilters(input: IssueFilterInput): readonly SQL[] {
