/**
 * `null` is unassigned. `undefined` does not filter. The `me` token is
 * resolved by the service before it reaches here; an unresolved token
 * matches nothing rather than every row.
 */
function assigneePredicate(
  assigneeId: IssueFilterInput["assigneeId"],
): SQL | undefined {
  if (assigneeId === undefined) return undefined;
  if (assigneeId === null) return isNull(issues.assigneeId);
  if (assigneeId === ME_TOKEN) return sql`1 = 0`;
  return eq(issues.assigneeId, assigneeId);
}

function authorPredicate(
  authorId: IssueFilterInput["authorId"],
): SQL | undefined {
  if (authorId === undefined) return undefined;
  if (authorId === ME_TOKEN) return sql`1 = 0`;
  return eq(issues.authorId, authorId);
}

/** Issues with no due date never match. A calendar date includes that whole UTC day. */
function duePredicate(
  dueBefore: IssueFilterInput["dueBefore"],
): SQL | undefined {
  if (dueBefore === undefined) return undefined;
  return and(
    isNotNull(issues.dueAt),
    lt(issues.dueAt, dueBeforeExclusiveBound(dueBefore)),
  );
}

/** An issue matches only when it carries every listed label. */
function labelPredicate(
  orgId: IssueFilterInput["orgId"],
  labelIds: IssueFilterInput["labelIds"],
): SQL | undefined {
  if (labelIds === undefined || labelIds.length === 0) return undefined;
  const matches = labelIds.map((labelId) =>
    inArray(
      issues.id,
      getDb()
        .select({ id: issueLabels.issueId })
        .from(issueLabels)
        .where(
          and(
            orgPredicate(issueLabels.orgId, orgId),
            eq(issueLabels.labelId, labelId),
          ),
        ),
    ),
  );
  return and(...matches);
}

/** Builds the shared predicate list behind `listIssues` and its count. */
function issueFilters(input: IssueFilterInput): readonly SQL[] {
  const filterLive = shouldFilterArchived(input);
  const scope: ArchiveScope =
    input.archivedOnly === true
      ? { archivedOnly: true }
      : filterLive
        ? {}
        : { includeArchived: true };

  const statuses =
    input.status === undefined || input.status.length === 0
      ? undefined
      : expandIssueStatuses(input.status);

  return compact(
    orgPredicate(issues.orgId, input.orgId),
    livePredicate(issues.archivedAt, scope),
    input.projectId === undefined
      ? undefined
      : eq(issues.projectId, input.projectId),
    statuses === undefined ? undefined : inArray(issues.status, statuses),
    input.priority === undefined || input.priority.length === 0
      ? undefined
      : inArray(issues.priority, [...input.priority]),
    assigneePredicate(input.assigneeId),
    authorPredicate(input.authorId),
    duePredicate(input.dueBefore),
    input.query === undefined
      ? undefined
      : or(
          like(issues.title, `%${input.query}%`),
          like(issues.description, `%${input.query}%`),
