  const { dueBefore: _dueBefore, ...rest } = filter;
  if (value === null || value.length === 0) return rest;
  return { ...rest, dueBefore: value as CalendarDate };
}

function archivedMode(filter: IssueFilter): string {
  if (filter.archivedOnly === true) return "only";
  if (filter.includeArchived === true) return "1";
  return "";
}

