pnpm exec tsx -e '
import { issueFilterSchema } from "./src/schemas/issue.ts";
import { exportIssuesSchema } from "./src/schemas/export.ts";
import { parseIssueFilterParams, issueFilterToParams } from "./src/hooks/issue-filter-params.ts";
import { dueBeforeExclusiveBound } from "./src/lib/date.ts";
import { expandIssueStatuses } from "./src/types/issue.ts";

const ORG = "01HZZZPPPPPPPPPPPPPPPPPPPP";
const USER = "01HZZZAAAAAAAAAAAAAAAAAAAA";

const open = issueFilterSchema.safeParse({ orgId: ORG, status: "open" });
console.log("status string open", open.success, open.success && open.data.status);
const groups = issueFilterSchema.safeParse({ orgId: ORG, status: ["open", "done"] });
console.log("status array groups", groups.success, groups.success && groups.data.status);
const bad = issueFilterSchema.safeParse({ orgId: ORG, status: "todo,nope" });
console.log("unknown refused", bad.success);
const date = issueFilterSchema.safeParse({ orgId: ORG, dueBefore: "2026-03-15" });
console.log("date", date.success, date.success && date.data.dueBefore);
const ts = issueFilterSchema.safeParse({ orgId: ORG, dueBefore: "2026-03-15T12:00:00.000Z" });
console.log("ts", ts.success, ts.success && ts.data.dueBefore);
const badDate = issueFilterSchema.safeParse({ orgId: ORG, dueBefore: "2026-02-31" });
console.log("bad date", badDate.success);
const me = issueFilterSchema.safeParse({ orgId: ORG, assigneeId: "me", authorId: "me" });
console.log("me", me.success, me.success && me.data.assigneeId, me.success && me.data.authorId);
const none = issueFilterSchema.safeParse({ orgId: ORG, assigneeId: "none" });
console.log("none", none.success, none.success && none.data.assigneeId);
const nil = issueFilterSchema.safeParse({ orgId: ORG, assigneeId: null });
console.log("null", nil.success, nil.success && nil.data.assigneeId);
const id = issueFilterSchema.safeParse({ orgId: ORG, assigneeId: USER });
console.log("id", id.success);
const empty = issueFilterSchema.parse({ orgId: ORG });
console.log("empty keys", Object.keys(empty), empty.limit, empty.includeArchived, empty.assigneeId);
const exp = exportIssuesSchema.safeParse({ orgId: ORG, status: "open", includeArchived: false, format: "csv" });
console.log("export", exp.success, exp.success && exp.data.status);
const codec = parseIssueFilterParams(new URLSearchParams("status=open,todo&assignee=me&archived=only&due_before=2026-03-15&label=01HZZZKKKKKKKKKKKKKKKKKKKK,01HZZZLLLLLLLLLLLLLLLLLLLL"));
console.log("codec", JSON.stringify(codec));
console.log("bound date", dueBeforeExclusiveBound("2026-03-15"));
console.log("bound ts", dueBeforeExclusiveBound("2026-03-15T12:00:00Z"));
console.log("round archived", issueFilterToParams({ archivedOnly: true }));
console.log("expand", expandIssueStatuses(["closed", "todo"]));
'
